<template>
  <section class="page function-detail-page">
    <header class="detail-heading"><button type="button" title="返回页面功能" aria-label="返回页面功能" @click="back"><ArrowLeft :size="18" /></button><div><nav><RouterLink to="/web/pages">页面管理</RouterLink><span>/</span><RouterLink v-if="workspace?.page" :to="`/web/pages/${workspace.page.id}`">{{ workspace.page.name }}</RouterLink><span>/</span><span>功能详情</span></nav><h2>{{ workspace?.feature.name || '功能详情' }}</h2><span class="meta">{{ featureTypes[workspace?.feature.data.feature_type] || '其他' }} · {{ workspace?.feature.data.script_version ? `脚本 #${workspace.feature.data.script_version}` : '未生成脚本' }}</span></div><div class="heading-actions"><button type="button" :disabled="!workspace" @click="generationTaskId = undefined; generationVisible = true"><Sparkles :size="16" />AI 生成脚本</button><button type="button" :disabled="!workspace" @click="editorVisible = true"><Pencil :size="15" />编辑功能</button><button type="button" title="刷新" aria-label="刷新" :disabled="loading" @click="load"><RefreshCw :size="16" /></button></div></header>
    <WebScriptTools :feature-id="featureId" :version-id="versionId" @saved="load" />
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="message" class="message" role="status">{{ message }}</p>
    <section v-if="proposal" class="discovery-review"><strong>待确认发现结果</strong><span>参数 {{ proposal.parameters?.length || 0 }} 个 · {{ proposal.candidate ? '操作脚本已生成' : '操作或定位待补充' }}</span><button type="button" :disabled="!proposal.candidate || actionBusy" @click="acceptDiscovery">确认保存脚本</button><button type="button" @click="proposalVisible = !proposalVisible">{{ proposalVisible ? '收起差异' : '查看差异' }}</button><ul v-if="proposal.warnings?.length"><li v-for="warning in proposal.warnings" :key="String(warning)">{{ warning }}</li></ul><div v-if="proposalVisible" class="proposal-grid"><div><h4>当前参数</h4><pre>{{ JSON.stringify(workspace?.parameters, null, 2) }}</pre></div><div><h4>发现参数</h4><pre>{{ JSON.stringify(proposal.parameters, null, 2) }}</pre></div><pre class="full">{{ JSON.stringify(proposal.candidate, null, 2) }}</pre></div></section>
    <nav class="workspace-tabs" aria-label="功能信息"><button v-for="tab in tabs" :key="tab.key" type="button" :class="{ active: view === tab.key }" @click="view = tab.key">{{ tab.label }}</button></nav>
    <section v-if="view === 'inputs'" class="input-overview">
      <WebParameterTable :parameters="workspace?.parameters || []" :selected="selectedParameter" @select="selectedParameter = $event" />
      <div class="screenshot-region"><div class="section-title"><h3>页面 / 弹窗截图</h3><select v-if="shots.length" v-model.number="shotIndex" aria-label="切换截图"><option v-for="(_, index) in shots" :key="index" :value="index">截图 {{ index + 1 }}</option></select></div><a v-if="shots[shotIndex]" :href="shotUrl(shots[shotIndex])" target="_blank" rel="noopener noreferrer"><img :src="shotUrl(shots[shotIndex])" :alt="`${workspace?.feature.name} 页面截图`" /></a><div v-else class="empty-shot">暂无截图</div><p v-if="selectedParameter" class="meta">{{ workspace?.parameters.find(p => p.key === selectedParameter)?.label }}</p></div>
    </section>
    <section v-else-if="view === 'script'" class="script-region"><div class="section-title"><h3>操作脚本</h3><select v-model.number="versionId" aria-label="脚本版本"><option :value="0">选择版本</option><option v-for="version in workspace?.versions" :key="version.id" :value="version.id">#{{ version.id }} · {{ version.status === 'verified' ? '已验证' : '待验证' }}</option></select><button type="button" :disabled="!versionId || actionBusy || versionId === workspace?.feature.data.script_version" @click="activate">启用此版本</button></div><div class="table-wrap"><table><thead><tr><th>#</th><th>步骤</th><th>动作</th><th>定位</th><th>输入 / 预期</th></tr></thead><tbody><tr v-for="(step,index) in displayedCandidate?.steps || []" :key="index"><td>{{ Number(index)+1 }}</td><td>{{ step.name }}</td><td>{{ step.action }}</td><td>{{ step.locator_type }} · {{ step.locator }}</td><td>{{ step.action === 'assert' ? step.expected : step.value }}</td></tr><tr v-if="!displayedCandidate?.steps?.length"><td colspan="5" class="empty">暂无脚本</td></tr></tbody></table></div></section>
    <section v-else-if="view === 'apis'" class="api-region"><div class="section-title"><h3>关联 API</h3><button type="button" @click="openApiBinding"><Link2 :size="15" />关联 API</button></div><div class="table-wrap"><table><thead><tr><th>API 名称</th><th>方法</th><th>路径</th><th>关联依据</th><th>操作</th></tr></thead><tbody><tr v-for="api in workspace?.interfaces" :key="api.relation_id"><td><RouterLink :to="`/api/interfaces/${api.id}`">{{ api.name }}</RouterLink></td><td>{{ api.data.method }}</td><td><code>{{ api.data.path }}</code></td><td>{{ api.relation_source === 'ai' ? 'AI 候选' : api.relation_source === 'network' ? '实际请求' : '人工确认' }}</td><td><button type="button" title="解除关联" aria-label="解除关联" @click="unlink(api.relation_id)"><Unlink :size="15" /></button></td></tr><tr v-if="!workspace?.interfaces.length"><td colspan="5" class="empty">暂无关联 API</td></tr></tbody></table></div><div v-if="workspace?.api_candidates.length"><h4>待确认 API 候选</h4><pre>{{ JSON.stringify(workspace.api_candidates, null, 2) }}</pre></div></section>
    <section class="case-region"><div class="section-title"><h3>输入内容用例 <small>{{ workspace?.cases.length || 0 }}</small></h3><div class="case-tools"><input v-model="caseKeyword" type="search" placeholder="搜索用例名称" aria-label="搜索用例名称" /><button type="button" :disabled="!workspace" @click="openCase()"><Plus :size="15" />新增用例</button><button type="button" :disabled="!selectedCases.length || running" @click="openRun(selectedCases)"><Play :size="15" />执行选中</button></div></div><div class="table-wrap"><table class="case-table"><thead><tr><th class="check-cell"><input type="checkbox" :checked="!!visibleCases.length && visibleCases.every(c => selectedCases.includes(c.id))" aria-label="全选用例" @change="toggleAll" /></th><th>用例名称</th><th>输入内容</th><th>脚本</th><th>优先级</th><th>操作</th></tr></thead><tbody><tr v-for="item in visibleCases" :key="item.id"><td><input v-model="selectedCases" type="checkbox" :value="item.id" :aria-label="`选择${item.name}`" /></td><td><button class="name-link" type="button" @click="openCase(item)">{{ item.name }}</button><small v-if="item.data.feature_revision && item.data.feature_revision !== workspace?.feature.data.revision" class="stale">功能有新版本</small></td><td class="input-summary" :title="JSON.stringify(caseInputs(item))">{{ JSON.stringify(caseInputs(item)) }}</td><td>{{ item.data.script_version ? `#${item.data.script_version}` : '历史快照' }}</td><td>{{ item.priority || 'P2' }}</td><td><div class="row-actions"><button type="button" title="执行用例" aria-label="执行用例" :disabled="running" @click="openRun([item.id])"><Play :size="15" /></button><button type="button" title="编辑用例" aria-label="编辑用例" @click="openCase(item)"><Pencil :size="15" /></button><button type="button" title="复制用例" aria-label="复制用例" @click="openCase(item, true)"><Copy :size="15" /></button><button type="button" title="删除用例" aria-label="删除用例" @click="deleteTarget = item"><Trash2 :size="15" /></button></div></td></tr><tr v-if="!visibleCases.length"><td colspan="6" class="empty">{{ loading ? '加载中' : '暂无输入用例' }}</td></tr></tbody></table></div><CommonPagination :page="casePage" :page-size="casePageSize" :total="filteredCases.length" @change="paginate" />
      <details v-if="workspace?.legacy_drafts.length"><summary>历史待确认用例 {{ workspace.legacy_drafts.length }}</summary><div v-for="draft in workspace.legacy_drafts" :key="draft.id" class="legacy-row"><span>{{ draft.name }}</span><button type="button" :disabled="actionBusy" @click="importDraft(draft.id)">确认导入用例</button></div></details>
    </section>
    <section v-if="task" class="execution-region"><div class="section-title"><h3>执行记录 #{{ task.id }}</h3><span :class="{ error: task.status === 'failed' }">{{ taskStates[task.status] || task.status }}</span><RouterLink to="/reports/records">全部记录</RouterLink></div><BrowserWindowPanel v-if="headedTask" :task-id="task.id" /><p v-if="task.data.error" class="error">{{ task.data.error }}</p><div v-for="(record,index) in records" :key="index" class="execution-evidence"><strong :class="{ error: record.status === 'failed' }">{{ record.name }} · {{ record.status === 'success' ? '通过' : '失败' }}</strong><p v-if="record.data.error" class="error">{{ record.data.error }}</p><div class="evidence-images"><a v-for="(shot,n) in record.data.screenshots || []" :key="n" :href="media(shot.screenshot_url)" target="_blank" rel="noopener noreferrer"><img v-if="shot.screenshot_url" :src="media(shot.screenshot_url)" :alt="shot.step_name || `步骤 ${shot.step_order}`" /></a></div><video v-if="record.data.video_url" :src="media(record.data.video_url)" controls preload="metadata" /></div><button v-if="task.status === 'failed'" type="button" @click="failureVisible = true"><Sparkles :size="15" />分析失败</button></section>
    <WebOperationControls :task="task" />
    <p v-for="(record,index) in records" :key="`result-${index}`" role="status">{{ record.data.result_label || (record.status === 'success' && !record.data.assertion_count ? '操作完成，业务结果未验证' : '') }}<span v-if="record.data.privacy_notice"> · {{ record.data.privacy_notice }}</span></p>
    <WebFeatureFormDialog :visible="editorVisible" :group-id="Number(workspace?.page?.id || 0)" :project-id="Number(workspace?.feature.project_id || 0)" :feature="workspace?.feature" @close="editorVisible = false" @saved="load" />
    <BusinessGenerationDrawer :visible="generationVisible" domain="WEB" :source-id="featureId" :source-name="workspace?.feature.name || ''" :initial-task-id="generationTaskId" :initial-prompt="workspace?.feature.description || ''" @close="generationVisible = false" @saved="load" />
    <Teleport to="body">
      <div v-if="caseEditorVisible" class="modal-backdrop" @click.self="closeCase"><section class="modal-panel case-editor" role="dialog" aria-modal="true"><header class="modal-header"><h3>{{ editingCaseId ? '编辑用例' : '新增用例' }}</h3><button type="button" title="关闭" aria-label="关闭" @click="closeCase"><X :size="18" /></button></header><form @submit.prevent="saveCase"><main><div class="form-grid"><label class="field full"><span>用例名称</span><input v-model.trim="caseForm.name" required maxlength="128" /></label><label class="field"><span>优先级</span><select v-model="caseForm.priority"><option v-for="p in ['P0','P1','P2','P3']" :key="p">{{ p }}</option></select></label><label class="field"><span>脚本版本</span><select v-model="caseForm.script_version"><option :value="null">当前脚本</option><option v-for="v in workspace?.versions" :key="v.id" :value="v.id">#{{ v.id }}</option></select></label><label class="field"><span>状态</span><select v-model="caseForm.status"><option value="active">启用</option><option value="disabled">停用</option></select></label><label class="check"><input v-model="caseForm.allow_invalid_inputs" type="checkbox" />异常输入用例</label></div><h4>输入内容</h4><WebCaseInputForm v-model="caseForm.input_info" :parameters="caseParameters" :secret-keys="caseSecretKeys" @valid="caseValid = $event" /><details v-if="Object.keys(legacyInputs).length"><summary>历史参数</summary><label v-for="(_, key) in legacyInputs" :key="key" class="field"><span>{{ key }}</span><input v-model="caseForm.input_info[key]" /></label></details><h4>预期结果</h4><div v-for="(assertion,index) in caseForm.expected_steps" :key="index" class="assertion-row"><select v-model="assertion.locator_type" aria-label="断言定位方式"><option v-for="kind in ['text','label','role','testid','css','xpath']" :key="kind">{{ kind }}</option></select><input v-model="assertion.locator" placeholder="成功标识定位" aria-label="成功标识定位" /><input v-model="assertion.expected" placeholder="预期文本" aria-label="预期文本" /><button type="button" title="删除断言" aria-label="删除断言" @click="caseForm.expected_steps.splice(index,1)"><Trash2 :size="15" /></button></div><button type="button" @click="caseForm.expected_steps.push({ name: '结果断言', action: 'assert', locator_type: 'text', locator: '', expected: '' })"><Plus :size="15" />添加断言</button><p v-if="caseError" class="error" role="alert">{{ caseError }}</p></main><footer class="modal-actions"><button type="button" :disabled="caseSaving" @click="closeCase">取消</button><button type="submit" :disabled="caseSaving || !caseValid">保存用例</button></footer></form></section></div>
      <div v-if="runVisible" class="modal-backdrop" @click.self="runVisible = false"><section class="modal-panel run-dialog" role="dialog" aria-modal="true"><h3>执行用例</h3><p>已选择 {{ runCaseIds.length }} 条用例</p><fieldset class="run-modes"><label><input v-model="headless" type="radio" :value="false" /><Monitor :size="16" />本地有头</label><label><input v-model="headless" type="radio" :value="true" /><MonitorOff :size="16" />本地无头</label></fieldset><label class="field"><span>执行节点</span><select v-model="nodeKey"><option value="">选择在线 Agent</option><option v-for="node in nodes" :key="node.id" :value="node.data.node_key">{{ node.name }}</option></select></label><label class="check"><input v-model="approveEffects" type="checkbox" />允许本次用例中的点击、填写和业务提交</label><label class="check"><input v-model="recordVideo" type="checkbox" />录制执行视频</label><p v-if="runError" class="error" role="alert">{{ runError }}</p><footer class="modal-actions"><button type="button" :disabled="actionBusy" @click="runVisible = false">取消</button><button type="button" :disabled="actionBusy || !nodeKey || running" @click="execute"><Play :size="15" />开始执行</button></footer></section></div>
      <div v-if="failureVisible" class="modal-backdrop" @click.self="failureVisible = false"><section class="modal-panel failure-dialog" role="dialog" aria-modal="true"><h3>执行失败</h3><label v-if="failedRecords.length > 1" class="field"><span>失败用例</span><select v-model.number="repairCaseId"><option v-for="r in failedRecords" :key="r.data.case_id" :value="r.data.case_id">{{ r.name }}</option></select></label><p class="error">{{ failedRecords.find(r => r.data.case_id === repairCaseId)?.data.error || task?.data.error || '执行中断' }}</p><p>是否使用 AI 分析原因并生成修复候选？</p><p v-if="repairError" class="error">{{ repairError }}</p><footer class="modal-actions"><button type="button" :disabled="actionBusy" @click="failureVisible = false">暂不修复</button><button type="button" :disabled="actionBusy || !repairCaseId" @click="repair"><Sparkles :size="15" />AI 分析修复</button></footer></section></div>
      <div v-if="deleteTarget" class="modal-backdrop"><section class="modal-panel confirm-panel" role="dialog" aria-modal="true"><h3>删除用例</h3><p>删除「{{ deleteTarget.name }}」？历史执行记录将保留。</p><p v-if="deleteError" class="error">{{ deleteError }}</p><footer class="modal-actions"><button type="button" :disabled="actionBusy" @click="deleteTarget = null">取消</button><button type="button" :disabled="actionBusy" @click="removeCase">删除</button></footer></section></div>
      <div v-if="apiBindingVisible" class="modal-backdrop"><section class="modal-panel api-binding" role="dialog" aria-modal="true"><h3>关联 API</h3><input v-model="apiKeyword" type="search" placeholder="搜索 API 名称或路径" /><div class="api-options"><label v-for="api in apiOptions.filter(a => `${a.name} ${a.data.path}`.includes(apiKeyword))" :key="api.id"><input v-model="apiIds" type="checkbox" :value="api.id" />{{ api.name }} · {{ api.data.method }} {{ api.data.path }}</label></div><p v-if="apiError" class="error">{{ apiError }}</p><footer class="modal-actions"><button type="button" :disabled="actionBusy" @click="apiBindingVisible = false">取消</button><button type="button" :disabled="!apiIds.length || actionBusy" @click="bindApis">关联</button></footer></section></div>
    </Teleport>
  </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowLeft, Copy, Link2, Monitor, MonitorOff, Pencil, Play, Plus, RefreshCw, Sparkles, Trash2, Unlink, X } from 'lucide-vue-next'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import CommonPagination from '../../components/common/CommonPagination.vue'
import BusinessGenerationDrawer from '../../components/generation/BusinessGenerationDrawer.vue'
import BrowserWindowPanel from '../../components/execution/BrowserWindowPanel.vue'
import WebFeatureFormDialog from '../../components/web-testing/WebFeatureFormDialog.vue'
import WebCaseInputForm from '../../components/web-testing/WebCaseInputForm.vue'
import WebScriptTools from '../../components/web-testing/WebScriptTools.vue'
import WebOperationControls from '../../components/web-testing/WebOperationControls.vue'
import WebParameterTable from '../../components/web-testing/WebParameterTable.vue'
import { getWebFeature, featureAction, saveWebInputCase, deleteWebInputCase } from '../../services/web-feature.service'
import { getAgentTask, listAgentNodes } from '../../services/agent.service'
import { listResources } from '../../services/resource.service'
import { createWebPageInterfaceRelations, deleteWebPageInterfaceRelation } from '../../services/web-page.service'
import { withScreenshotAccessToken as media } from '../../utils/screenshotUrl'
import { pageTabKey, usePageTabsStore } from '../../store/page-tabs'
import type { ResourceItem } from '../../types/resource'
import type { AgentNode, AgentTask } from '../../types/agent'
import type { WebFeatureDetail } from '../../types/web-feature'
const route = useRoute(), router = useRouter(), featureId = Number(route.params.featureId)
const workspace = ref<WebFeatureDetail | null>(null), loading = ref(false), error = ref(''), message = ref(''), view = ref('inputs'), actionBusy = ref(false)
const editorVisible = ref(false), generationVisible = ref(false), generationTaskId = ref<number | undefined>(), versionId = ref(0), shotIndex = ref(0), selectedParameter = ref(''), proposalVisible = ref(false)
const tabs = [{ key:'inputs', label:'参数与截图' }, { key:'script', label:'操作脚本' }, { key:'apis', label:'关联 API' }]
const featureTypes: Record<string,string> = { page:'页面', login:'登录', query:'查询', add:'新增', edit:'编辑', delete:'删除', detail:'详情', import:'导入', export:'导出', audit:'审核', submit:'提交', other:'其他' }
const taskStates: Record<string,string> = { pending:'排队中', running:'执行中', success:'通过', failed:'失败', canceled:'已取消' }
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value))
const proposal = computed(() => workspace.value?.feature.data.discovery_proposal)
const shots = computed(() => workspace.value?.screenshots.length ? workspace.value.screenshots : proposal.value?.screenshots || [])
const displayedCandidate = computed(() => workspace.value?.versions.find(v => v.id === versionId.value)?.data.candidate || workspace.value?.candidate)
const caseKeyword = ref(''), casePage = ref(1), casePageSize = ref(10), selectedCases = ref<number[]>([])
const filteredCases = computed(() => workspace.value?.cases.filter(c => c.name.includes(caseKeyword.value)) || [])
const visibleCases = computed(() => filteredCases.value.slice((casePage.value-1)*casePageSize.value,casePage.value*casePageSize.value))
const caseEditorVisible = ref(false), editingCaseId = ref<number | undefined>(), caseSaving = ref(false), caseError = ref(''), caseValid = ref(true)
const emptyCase = () => ({ name:'', input_info:{} as Record<string,any>, expected_steps:[] as Record<string,any>[], priority:'P2', status:'active', allow_invalid_inputs:false, script_version:null as number | null, copy_from_case_id:null as number | null })
const caseSecretKeys = ref<string[]>([])
const caseForm = ref(emptyCase())
const caseParameters = computed(() => workspace.value?.versions.find(v => v.id === caseForm.value.script_version)?.data.parameters || workspace.value?.parameters || [])
const legacyInputs = computed(() => Object.fromEntries(Object.entries(caseForm.value.input_info).filter(([key]) => !caseParameters.value.some((p: any) => p.key === key))))
const deleteTarget = ref<ResourceItem | null>(null), deleteError = ref('')
const runVisible = ref(false), runCaseIds = ref<number[]>([]), headless = ref(sessionStorage.getItem('web-function-mode') !== 'headed'), nodeKey = ref(''), nodes = ref<AgentNode[]>([]), approveEffects = ref(false), recordVideo = ref(true), runError = ref('')
const task = ref<AgentTask | null>(null), failureVisible = ref(false), repairCaseId = ref(0), repairError = ref('')
const running = computed(() => ['pending','running'].includes(task.value?.status || ''))
const headedTask = computed(() => (task.value?.data.payload?.execution as Record<string,any> | undefined)?.mode === 'local_headed')
const records = computed<Record<string,any>[]>(() => (task.value?.data.result?.records || []) as Record<string,any>[])
const failedRecords = computed(() => records.value.filter(r => r.status === 'failed'))
const apiBindingVisible = ref(false), apiOptions = ref<ResourceItem[]>([]), apiKeyword = ref(''), apiIds = ref<number[]>([]), apiError = ref('')
const taskStorageKey = `web-function-task:${featureId}`
let timer: ReturnType<typeof setTimeout> | undefined, epoch = 0, promptedTaskId = 0, pollErrors = 0
onMounted(async () => { usePageTabsStore().setTitle(pageTabKey(route), '功能详情'); await load(); const savedTask = Number(sessionStorage.getItem(taskStorageKey)); if (savedTask) void poll(savedTask) })
onBeforeUnmount(() => { ++epoch; clearTimeout(timer) })
async function load() { loading.value = true; error.value = ''; try { const result = await getWebFeature(featureId); if (route.params.pageId && Number(route.params.pageId) !== result.page?.id) throw new Error('功能不属于当前页面'); workspace.value = result; versionId.value = Number(result.feature.data.script_version || 0); selectedCases.value = selectedCases.value.filter(id => result.cases.some(c => c.id === id)); casePage.value = Math.min(casePage.value, Math.max(1, Math.ceil(filteredCases.value.length / casePageSize.value))) } catch (e) { error.value = detailError(e) } finally { loading.value = false } }
function back() { router.push(workspace.value?.page ? `/web/pages/${workspace.value.page.id}` : '/web/pages') }
function shotUrl(path: string) { return media(`/api/v1/screenshots/${encodeURIComponent(path.split(/[\\/]/).pop() || '')}`) }
function caseInputs(item: ResourceItem) { const data = item.data as Record<string,any>; return data.input_info || data.request?.input_info || data.variables || data.request?.variables || {} }
function paginate(page: number,size: number) { casePage.value = page; casePageSize.value = size }
function toggleAll(event: Event) { const checked = (event.target as HTMLInputElement).checked; selectedCases.value = checked ? [...new Set([...selectedCases.value,...visibleCases.value.map(c => c.id)])] : selectedCases.value.filter(id => !visibleCases.value.some(c => c.id === id)) }
function openCase(item?: ResourceItem, copy = false) { editingCaseId.value = copy ? undefined : item?.id; caseValid.value = true; caseError.value = ''; const parameters = workspace.value?.parameters || []; const data = (item?.data || {}) as Record<string,any>; caseSecretKeys.value = data.secret_keys || []; const defaults = Object.fromEntries(parameters.filter(p => !['manual','password'].includes(p.type) && p.default_value != null).map(p => [p.key,p.default_value])); caseForm.value = { ...emptyCase(), name:item ? item.name + (copy ? ' 副本' : '') : '', input_info:clone(item ? caseInputs(item) : defaults), expected_steps:clone(data.expected_steps || []), priority:String(item?.priority || 'P2'), status:item?.status || 'active', allow_invalid_inputs:Boolean(data.allow_invalid_inputs), script_version:data.script_version || null, copy_from_case_id:copy ? item?.id || null : null }; caseEditorVisible.value = true }
function closeCase() { if (!caseSaving.value) { caseEditorVisible.value = false; caseForm.value = emptyCase() } }
async function saveCase() { caseSaving.value = true; caseError.value = ''; try { await saveWebInputCase(featureId,caseForm.value,editingCaseId.value); caseForm.value = emptyCase(); caseEditorVisible.value = false; await load() } catch(e) { caseError.value = detailError(e) } finally { caseSaving.value = false } }
async function removeCase() { if (!deleteTarget.value) return; actionBusy.value = true; deleteError.value = ''; try { await deleteWebInputCase(featureId,deleteTarget.value.id); deleteTarget.value = null; await load() } catch(e) { deleteError.value = detailError(e) } finally { actionBusy.value = false } }
async function perform(action: string,data = {}) { actionBusy.value = true; error.value = ''; try { await featureAction(featureId,action,data); await load() } catch(e) { error.value = detailError(e) } finally { actionBusy.value = false } }
function activate() { return perform('versions/select',{version_id:versionId.value}) }
function acceptDiscovery() { return perform('discovery/accept') }
function importDraft(id: number) { return perform(`import-drafts/${id}`) }
async function openRun(ids: number[]) { runCaseIds.value = [...ids]; runVisible.value = true; runError.value = ''; approveEffects.value = false; try { const result = await listAgentNodes({pageSize:100}); nodes.value = result.items.filter(n => n.status === 'active' && ['online','busy'].includes(n.data.agent_status) && n.data.capabilities?.includes('case_execution') && Date.now() - Date.parse(n.data.last_seen_at || '') < 90000); if (!nodes.value.some(n => n.data.node_key === nodeKey.value)) nodeKey.value = (nodes.value.find(n => n.data.default_local_headed) || nodes.value[0])?.data.node_key || '' } catch(e) { runError.value = detailError(e) } }
async function execute() { actionBusy.value = true; runError.value = ''; try { const queued = await featureAction(featureId,'run',{case_ids:runCaseIds.value,headless:headless.value,node_key:nodeKey.value,approve_side_effects:approveEffects.value,record_video:recordVideo.value}); sessionStorage.setItem('web-function-mode',headless.value ? 'headless' : 'headed'); sessionStorage.setItem(taskStorageKey,String(queued.agent_task_id)); runVisible.value = false; clearTimeout(timer); ++epoch; await poll(queued.agent_task_id) } catch(e) { runError.value = detailError(e) } finally { actionBusy.value = false } }
async function poll(id: number) {
  const current = epoch
  try {
    const result = await getAgentTask(id)
    if (current !== epoch) return
    const owned = (result.data.payload?.cases || []) as any[]
    if (!owned.some(c => c.source_id === featureId && c.project_id === workspace.value?.feature.project_id)) {
      sessionStorage.removeItem(taskStorageKey); error.value = '执行任务不属于当前功能'; return
    }
    pollErrors = 0; task.value = result
    if (['pending','running'].includes(result.status)) timer = setTimeout(() => void poll(id),2000)
    else if (result.status === 'failed' && promptedTaskId !== id) {
      promptedTaskId = id; repairCaseId.value = Number(failedRecords.value[0]?.data.case_id || 0); failureVisible.value = true
    }
  } catch(e) {
    if (current === epoch) {
      error.value = detailError(e)
      if (++pollErrors <= 3) timer = setTimeout(() => void poll(id),5000)
    }
  }
}
async function repair() { if (!task.value) return; actionBusy.value = true; repairError.value = ''; try { const queued = await featureAction(featureId,'repair',{agent_task_id:task.value.id,case_id:repairCaseId.value}); generationTaskId.value = queued.task_id; failureVisible.value = false; generationVisible.value = true } catch(e) { repairError.value = detailError(e) } finally { actionBusy.value = false } }
async function openApiBinding() { apiBindingVisible.value = true; apiError.value = ''; apiIds.value = []; apiKeyword.value = ''; try { apiOptions.value = (await listResources('/api-testing/interfaces',{project_id:workspace.value?.feature.project_id,pageSize:200})).items } catch(e) { apiError.value = detailError(e) } }
async function bindApis() { if (!workspace.value?.page) return; actionBusy.value = true; apiError.value = ''; try { await createWebPageInterfaceRelations(workspace.value.page.id,apiIds.value,featureId); apiBindingVisible.value = false; await load() } catch(e) { apiError.value = detailError(e) } finally { actionBusy.value = false } }
async function unlink(id: number) { if (!workspace.value?.page) return; try { await deleteWebPageInterfaceRelation(workspace.value.page.id,id); await load() } catch(e) { error.value = detailError(e) } }
function detailError(e: unknown) { return e instanceof Error ? e.message : '操作失败' }
</script>
